$conflicts=$v.counts.items >> [table:filter]{where:($r)=>$r.count>1}; assert len($conflicts)==0,"동일 주문번호의 비동일 행",$conflicts;
$p=[self:read]{path:$root+"/prepared.json"};
$valid=$v.unique >> [table:filter]{where:($r)=>$r.status=="eligible"} >> [table:sort]{by:["sku","seq","order"]};
$excluded=$v.unique >> [table:filter]{where:($r)=>$r.status!="eligible"};
$lots=$p.data.lots >> [table:sort]{by:["sku","received","lot"]};
$w=[self:write]{path:$root+"/fifo_input.json",content:json({raw_orders:$v.raw_orders,unique_orders:$v.unique_orders,duplicate_rows:$v.raw_orders-$v.unique_orders,valid:$valid,excluded:$excluded,lots:$lots})};
return {conflicts:len($conflicts),eligible:len($valid),excluded:$excluded,path:$w.path}

$d=([self:read]{path:$root+"/allocated.json"}).data;
$p=([self:read]{path:$root+"/fifo_input.json"}).data;
$o=$d.orders >> [table:sort]{by:"order"};
$a=$d.allocations >> [table:sort]{by:["order","lot"]};
$l=$d.lots >> [table:sort]{by:"lot"};
$t=$o >> [table:compute]{set:($r)=>{all:"total",requested:($r.status=="invalid_qty" or $r.status=="unknown_sku") ? 0 : $r.qty}} >> [table:groupby]{by:"all",agg:{requested:["sum","requested"],allocated:["sum","allocated"],shortage:["sum","shortage"],cost:["sum","cost"]}};
$lt=$l >> [table:compute]{set:($r)=>{all:"total"}} >> [table:groupby]{by:"all",agg:{remaining:["sum","remaining"]}};
$states=$o >> [table:groupby]{by:"status"};
[def:状態数]($items,$status){$rows=$items >> [table:filter]{where:($r)=>$r.status==$status}; return len($rows)==0 ? 0 : $rows[0].count}
$s={raw_orders:$p.raw_orders,unique_orders:len($o),duplicate_rows:$p.duplicate_rows,lots:len($l),requested:$t.items[0].requested,allocated:$t.items[0].allocated,shortage:$t.items[0].shortage,remaining:$lt.items[0].remaining,cost:$t.items[0].cost,fulfilled_orders:[fn:状態数]{items:$states.items,status:"fulfilled"},partial_orders:[fn:状態数]{items:$states.items,status:"partial"},shortage_orders:[fn:状態数]{items:$states.items,status:"shortage"},cancelled_orders:0,invalid_qty_orders:[fn:状態数]{items:$states.items,status:"invalid_qty"},unknown_sku_orders:[fn:状態数]{items:$states.items,status:"unknown_sku"}};
$r={summary:$s,orders:$o,allocations:$a,lots:$l,unknown_cancellations:[]};
$top=$o >> [table:filter]{where:($r)=>$r.shortage>0} >> [table:compute]{set:($r)=>{negative_shortage:0-$r.shortage}} >> [table:sort]{by:["negative_shortage","order"]} >> [table:take]{n:10};
$summarylines=map(entries($s),($e)=>f"| ${$e[0]} | ${$e[1]} |");
$statelines=map(["fulfilled","partial","shortage","cancelled","invalid_qty","unknown_sku"],($status)=>f"| ${$status} | ${get($s,$status+"_orders")} |");
$toplines=map($top,($v)=>f"| ${$v.order} | ${$v.sku} | ${$v.qty} | ${$v.allocated} | ${$v.shortage} |");
$report="# 합성 창고 FIFO 배분 보고서

## 요약

| 지표 | 값 |
| --- | ---: |
"+join("
",$summarylines)+"

## 6가지 상태별 주문수

| 상태 | 주문수 |
| --- | ---: |
"+join("
",$statelines)+"

## 부족량 상위 10 주문

부족량이 양수인 주문만, 부족량 내림차순·동률 order 사전순.

| order | sku | qty | allocated | shortage |
| --- | --- | ---: | ---: | ---: |
"+join("
",$toplines)+"

## FIFO·제외 규칙

- 알려진 품목은 skus.json 전체를 기준으로 한다. 재고가 없는 알려진 품목도 유효 주문에 포함한다.
- order, sku, seq, qty의 원문 필드값이 모두 동일한 행만 한 번 처리하며 중복 제거 전 정규화하지 않는다. 동일 order의 비동일 행은 없음을 확인했다.
- 양의 정수 수량만 유효하다. 빈칸·미정·0·음수·소수는 invalid_qty이며 unknown_sku보다 우선한다. 유효 수량은 정수, 무효 수량은 null이다.
- 품목별 주문은 숫자 seq 오름차순, 동률 order 사전순이다. 입고는 received 오름차순, 동률 lot 사전순이다. 모든 입고를 사용 가능하게 취급하며 별도의 날짜 제한은 없다.
- 부분 배분을 허용하고 소진 뒤 부족량을 기록한다. 배분 행은 양수만 기록하며 원가는 수량×입고 단가이다. 입력 단가는 모두 정수로 확인되어 정수 연산으로 정밀도를 보존하고 반올림하지 않았다.
- 제외 주문의 allocated/cost/shortage는 0이며 requested에서 제외한다. 취소는 없으므로 cancelled_orders=0, unknown_cancellations=[]이다. 실제 주문·예약·발송은 수행하지 않았다.
- 출력 정렬: orders는 order순, allocations는 order/lot순, lots는 lot순이다.

## 입력 출처

"+$sources+"

## 검증 범위

저장 후 result.json과 이 보고서를 재읽어 전체 행 수·상태·자료형·정렬, 주문별·입고별·품목별·전체 수량보존, 배분 원가, 누적 구간 교차에 의한 독립 FIFO 대사, 요약 15개 수치·상태 6개·부족 상위 10건 일치를 검증한다.
";
